         (e.exp_score IS NULL AND r.day1_hot_score IS NULL AND r.day1_hot_flag IS NULL)
         OR (ABS(r.day1_hot_score - e.exp_score) <= 0.1 AND r.day1_hot_flag = e.exp_hot)) AS ok
